// Lọc email job alert (Upwork, Fiverr, Freelancer, PeoplePerHour...) → danh sách job cho AI Office.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const from = String(j.from?.value?.[0]?.address || j.from || '').toLowerCase();
  const platform = ['upwork', 'fiverr', 'freelancer', 'peopleperhour', 'guru', 'toptal'].find((p) => from.includes(p));
  if (!platform) continue;
  const text = String(j.textPlain || j.text || j.textHtml || j.html || '');
  const title = String(j.subject || '').replace(/^(new job|job alert|new project|new jobs?)[:\-\s]*/i, '').trim();
  const urls = [...new Set((text.match(/https?:\/\/[^\s"'<>)\]]+/g) || [])
    .filter((u) => /\/(jobs?|projects?|gigs?)\//i.test(u))
    .map((u) => u.split('?')[0]))];
  if (urls.length === 0) out.push({ id: `${platform}:${j.messageId || title}`, platform, title, url: null, description: text.slice(0, 3000) });
  for (const url of urls.slice(0, 15)) out.push({ id: url, platform, title, url, description: text.slice(0, 3000) });
}
return out.length ? [{ json: { jobs: out } }] : [];
